import React, { useState, useCallback, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import AppHeader from "@/components/AppHeader";
import AuthDialog from "@/components/AuthDialog";
import JobSidebar from "@/components/JobSidebar";
import JobDetailView from "@/components/JobDetailView";
import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
import { toast } from "sonner";

export interface PastJob {
  id: string;
  title: string | null;
  job_description: string;
  status: string;
  created_at: string;
  resume_count: number;
  jd_analysis_json: any;
  dynamic_weights_json: Record<string, number> | null;
}

export interface Result {
  id: string;
  resume_id: string;
  overall_score: number;
  missing_skills: string[];
  red_flags: any;
  summary: string | null;
  interview_questions: any;
  filename: string;
  file_path: string | null;
  candidate_name: string | null;
  candidate_email?: string | null;
  candidate_phone?: string | null;
  candidate_location?: string | null;
  // Dynamic scoring fields
  hard_fit?: boolean;
  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
  confidence?: number;
  strengths_json?: string[];
  gaps_json?: string[];
  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string };
  matched_must_haves?: string[];
  missing_must_haves?: string[];
  scoring_version?: string;
  pending?: boolean;
}

export interface ExistingResume {
  id: string;
  filename: string;
  file_path: string | null;
  candidate_name: string | null;
  created_at: string;
}

const Index = () => {
  const { user } = useAuth();

  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
  const [results, setResults] = useState<Result[]>([]);
  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
  const [authOpen, setAuthOpen] = useState(false);

  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;

  const fetchPastJobs = useCallback(async () => {
    if (!user) return;
    setLoadingPastJobs(true);
    try {
      const { data: jobs } = await supabase
        .from("jobs")
        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, resumes(count)")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(50);
      if (jobs) {
        setPastJobs(jobs.map((j: any) => ({
          id: j.id,
          title: j.title,
          job_description: j.job_description,
          status: j.status,
          created_at: j.created_at,
          resume_count: j.resumes?.[0]?.count ?? 0,
          jd_analysis_json: j.jd_analysis_json,
          dynamic_weights_json: j.dynamic_weights_json,
        })));
      }
    } catch (err) {
      console.error("Failed to load past jobs:", err);
    } finally {
      setLoadingPastJobs(false);
    }
  }, [user]);

  useEffect(() => {
    fetchPastJobs();
  }, [fetchPastJobs]);

  const loadJobData = async (jobId: string) => {
    setSelectedJobId(jobId);
    try {
      const [resumesRes, resumeListRes] = await Promise.all([
        supabase
          .from("resumes")
          .select("id, filename, file_path, candidate_name, created_at")
          .eq("job_id", jobId)
          .order("created_at", { ascending: false }),
        supabase
          .from("resumes")
          .select("id, filename, file_path, candidate_name, parsed_json")
          .eq("job_id", jobId),
      ]);

      const resumes = resumesRes.data ?? [];
      setExistingResumes(resumes);

      const resumeData = (resumeListRes.data ?? []) as Array<{
        id: string;
        filename: string;
        file_path: string | null;
        candidate_name: string | null;
        parsed_json?: any;
      }>;
      if (resumeData.length === 0) {
        setResults([]);
        return;
      }

      const resumeIds = resumeData.map((r) => r.id);
      const { data: resultData } = await supabase
        .from("results")
        .select("id, resume_id, overall_score, missing_skills, red_flags, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
        .in("resume_id", resumeIds);

      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
      const merged: Result[] = (resultData ?? []).map((r: any) => {
        const resume = resumeMap.get(r.resume_id);
        const parsed = resume?.parsed_json as any;
        return {
          ...r,
          skill_score: r.skill_score ?? 0,
          experience_score: r.experience_score ?? 0,
          education_score: r.education_score ?? 0,
          overall_score: r.overall_score ?? 0,
          missing_skills: r.missing_skills ?? [],
          filename: resume?.filename ?? "Unknown",
          file_path: resume?.file_path ?? null,
          candidate_name: resume?.candidate_name ?? null,
          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
        };
      });
      merged.sort((a, b) => b.overall_score - a.overall_score);
      setResults(merged);
    } catch (err) {
      console.error("Failed to load job data:", err);
      toast.error("Failed to load job data");
    }
  };

  const handleNewJob = () => {
    setSelectedJobId(null);
    setResults([]);
    setExistingResumes([]);
  };

  const handleJobCreated = (job: PastJob) => {
    setPastJobs((prev) => [job, ...prev]);
    setSelectedJobId(job.id);
    loadJobData(job.id);
  };

  const handleRenameJob = (jobId: string, newTitle: string) => {
    setPastJobs((prev) =>
      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
    );
  };

  const handleDeleteJob = async (jobId: string) => {
    try {
      await supabase.from("resumes").delete().eq("job_id", jobId);
      await supabase.from("jobs").delete().eq("id", jobId);
      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
      if (selectedJobId === jobId) handleNewJob();
      toast.success("Job deleted");
    } catch {
      toast.error("Failed to delete job");
    }
  };

  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
    setPastJobs((prev) =>
      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
    );
  };

  const requireAuth = useCallback(() => {
    if (!user) { setAuthOpen(true); return true; }
    return false;
  }, [user]);

  return (
    <SidebarProvider className="h-svh overflow-hidden">
      <JobSidebar
        pastJobs={pastJobs}
        selectedJobId={selectedJobId}
        loadingPastJobs={loadingPastJobs}
        onSelectJob={loadJobData}
        onNewJob={handleNewJob}
        onRenameJob={handleRenameJob}
        onDeleteJob={handleDeleteJob}
        onAuthRequired={() => setAuthOpen(true)}
        isAuthenticated={!!user}
      />

      <SidebarInset className="h-svh overflow-y-auto">
        <AppHeader />
        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
          <SidebarTrigger />
          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
        </div>
        <JobDetailView
          selectedJobId={selectedJobId}
          selectedJob={selectedJob}
          results={results}
          setResults={setResults}
          existingResumes={existingResumes}
          setExistingResumes={setExistingResumes}
          onJobCreated={handleJobCreated}
          onAuthRequired={() => setAuthOpen(true)}
          isAuthenticated={!!user}
          onJobUpdated={handleJobUpdated}
        />
      </SidebarInset>

      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
    </SidebarProvider>
  );
};

export default Index;

import { useState, useCallback, useRef, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { usePlatformConfig } from "@/hooks/usePlatformConfig";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Progress } from "@/components/ui/progress";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle
} from "@/components/ui/alert-dialog";
import { toast } from "sonner";
import {
  Upload, Copy, Loader2, FileText,
  AlertTriangle, X, Trash2, RefreshCw, CheckCircle2
} from "lucide-react";
import ScoreSummaryCards from "@/components/ScoreSummaryCards";
import CandidateRow from "@/components/CandidateRow";
import type { PastJob, Result, ExistingResume } from "@/pages/Index";

interface JobDetailViewProps {
  selectedJobId: string | null;
  selectedJob: PastJob | null;
  results: Result[];
  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
  existingResumes: ExistingResume[];
  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
  onJobCreated: (job: PastJob) => void;
  onAuthRequired: () => void;
  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
  isAuthenticated?: boolean;
}

interface UploadedFile {
  file: File;
  name: string;
}

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const JobDetailView = ({
  selectedJobId,
  selectedJob,
  results,
  setResults,
  existingResumes,
  setExistingResumes,
  onJobCreated,
  onAuthRequired,
  onJobUpdated,
  isAuthenticated = true,
}: JobDetailViewProps) => {
  const { user, profile, refreshProfile } = useAuth();
  const { data: config } = usePlatformConfig();

  const [jobDescription, setJobDescription] = useState("");
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [ranking, setRanking] = useState(false);
  const [rankingProgress, setRankingProgress] = useState(0);
  const [scoredCount, setScoredCount] = useState(0);
  const [totalToScore, setTotalToScore] = useState(0);
  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
  const [dragOver, setDragOver] = useState(false);
  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [analyzingJd, setAnalyzingJd] = useState(false);
  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(new Set());

  const resultsRef = useRef<HTMLDivElement>(null);
  const rankingFilesRef = useRef<Set<string>>(new Set());
  const maxResumes = config?.max_resumes_per_job ?? 10;
  const maxFileSizeMb = config?.max_file_size_mb ?? 5;

  const isNewJobMode = selectedJobId === null;
  const isExistingJob = selectedJobId !== null && selectedJob !== null;

  const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const formatCandidateName = (filename: string) => {
    const name = filename.replace(/\.\w+$/, "");
    if (UUID_REGEX.test(name)) return `Candidate`;
    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
  };

  // Merge unranked resumes
  const resultResumeIds = new Set(results.map((r) => r.resume_id));
  const pendingResumes: Result[] = existingResumes
    .filter((r) => !resultResumeIds.has(r.id))
    .map((r) => ({
      id: `pending-${r.id}`,
      resume_id: r.id,
      skill_score: 0, experience_score: 0, education_score: 0, overall_score: 0,
      missing_skills: [], red_flags: {}, summary: null, interview_questions: null,
      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
      pending: true,
    }));
  const allResults = [...results, ...pendingResumes];

  // Selection helpers
  const toggleSelectResume = (resumeId: string) => {
    setSelectedResumes((prev) => {
      const next = new Set(prev);
      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
      return next;
    });
  };
  const toggleSelectAll = () => {
    if (selectedResumes.size === allResults.length) setSelectedResumes(new Set());
    else setSelectedResumes(new Set(allResults.map((r) => r.resume_id)));
  };

  // Delete logic
  const deleteResume = async (resumeId: string, filePath: string | null) => {
    if (filePath) await supabase.storage.from("resumes").remove([filePath]);
    await supabase.from("results").delete().eq("resume_id", resumeId);
    await supabase.from("resumes").delete().eq("id", resumeId);
    setResults((prev: Result[]) => prev.filter((r) => r.resume_id !== resumeId));
    setExistingResumes((prev: ExistingResume[]) => prev.filter((r) => r.id !== resumeId));
    setSelectedResumes((prev) => { const next = new Set(prev); next.delete(resumeId); return next; });
  };

  const handleDeleteConfirm = async () => {
    if (!deleteConfirm) return;
    setDeleting(true);
    try {
      if (deleteConfirm.type === "single" && deleteConfirm.resumeId) {
        await deleteResume(deleteConfirm.resumeId, deleteConfirm.filePath ?? null);
        toast.success("Resume deleted");
      } else if (deleteConfirm.type === "bulk") {
        const toDelete = allResults.filter((r) => selectedResumes.has(r.resume_id));
        for (const r of toDelete) await deleteResume(r.resume_id, r.file_path);
        toast.success(`${toDelete.length} resume(s) deleted`);
      }
    } catch { toast.error("Failed to delete"); }
    finally { setDeleting(false); setDeleteConfirm(null); }
  };

  // File handling
  const handleFileDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault(); setDragOver(false);
    const dropped = Array.from(e.dataTransfer.files).filter(
      (f) => f.type === "application/pdf" || f.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    );
    addFiles(dropped);
  }, [files, maxResumes, maxFileSizeMb]);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) addFiles(Array.from(e.target.files));
  };

  const addFiles = (newFiles: File[]) => {
    const currentCount = isExistingJob ? existingResumes.length + files.length : files.length;
    const valid = newFiles.filter((f) => {
      if (f.size > maxFileSizeMb * 1024 * 1024) { toast.error(`${f.name} exceeds ${maxFileSizeMb}MB limit`); return false; }
      return true;
    });
    const remaining = maxResumes - currentCount;
    if (valid.length > remaining) toast.error(`Max ${maxResumes} resumes per job`);
    const toAdd = valid.slice(0, Math.max(0, remaining)).map((f) => ({ file: f, name: f.name }));
    setFiles((prev) => [...prev, ...toAdd]);
  };

  const removeFile = (index: number) => setFiles((prev) => prev.filter((_, i) => i !== index));
  const toggleRow = (id: string) => {
    setExpandedRows((prev) => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  };

  const copyInboxEmail = () => {
    if (profile?.inbox_email) { navigator.clipboard.writeText(profile.inbox_email); toast.success("Inbox email copied!"); }
  };

  const validate = (): string[] => {
    const errors: string[] = [];
    if (isNewJobMode && !jobDescription.trim()) errors.push("Job description is required.");
    const filesToCheck = files.filter(f => !rankingFilesRef.current.has(f.name));
    if (filesToCheck.length === 0) errors.push("Upload at least one resume.");
    if (user && (profile?.credits ?? 0) < Math.min(filesToCheck.length, 20)) {
      errors.push(`Not enough credits. You need ${Math.min(filesToCheck.length, 20)} but have ${profile?.credits ?? 0}.`);
    }
    return errors;
  };

  // ── Analyze JD ──────────────────────────────────────────────
  const analyzeJd = async (jobId: string) => {
    setAnalyzingJd(true);
    try {
      const response = await fetch(
        `https://zkzontawprihrzpayeam.supabase.co/functions/v1/analyze-jd`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
          },
          body: JSON.stringify({ job_id: jobId }),
        }
      );
      if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.error || "JD analysis failed");
      }
      const data = await response.json();
      if (onJobUpdated) {
        onJobUpdated(jobId, {
          jd_analysis_json: data.jd_analysis,
          dynamic_weights_json: data.dynamic_weights,
        });
      }
      return data;
    } catch (err: any) {
      toast.error(err.message || "JD analysis failed");
      throw err;
    } finally {
      setAnalyzingJd(false);
    }
  };

  // ── Auto-rank ───────────────────────────────────────────────
  const autoRankTriggered = useRef(false);
  useEffect(() => {
    const unrankedFiles = files.filter(f => !rankingFilesRef.current.has(f.name));
    if (unrankedFiles.length > 0 && !ranking && !autoRankTriggered.current) {
      if (isNewJobMode && !jobDescription.trim()) return;
      autoRankTriggered.current = true;
      handleRankClick();
    }
    if (files.length === 0 && !ranking) autoRankTriggered.current = false;
  }, [files, ranking, isNewJobMode, jobDescription]);

  const handleRankingError = (err: any) => {
    const msg: string = err?.message || "Ranking failed.";
    if (msg.includes("Insufficient credits") || err?.status === 402) {
      setRankingError({ type: "credits", message: "You don't have enough credits to rank these resumes." });
    } else if (msg.includes("Rate limit") || err?.status === 429) {
      setRankingError({ type: "rate_limit", message: "Too many jobs in a short time. Please wait a minute and try again." });
    } else {
      setRankingError({ type: "generic", message: msg });
      toast.error(msg);
    }
  };

  const handleRankClick = () => {
    if (!user) { onAuthRequired(); return; }
    setRankingError(null);
    const errors = validate();
    setValidationErrors(errors);
    if (errors.length > 0) return;
    if (isExistingJob) handleRankExisting(); else handleRankNew();
  };

  const handleRankNew = async () => {
    if (!user) return;
    const filesToRank = [...files];
    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
    setRanking(true); setResults([]); setRankingError(null);
    setRankingProgress(5); setScoredCount(0); setTotalToScore(filesToRank.length);

    try {
      const autoTitle = (() => {
        const firstLine = jobDescription.trim().split("\n")[0].trim();
        return firstLine.slice(0, 50).trim() || `Job - ${new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`;
      })();

      const { data: job, error: jobError } = await supabase
        .from("jobs")
        .insert({ user_id: user.id, job_description: jobDescription, status: "pending", title: autoTitle } as any)
        .select("id")
        .single();
      if (jobError || !job) throw new Error(jobError?.message || "Failed to create job");
      setRankingProgress(10);

      const analysisData = await analyzeJd(job.id);
      setRankingProgress(25);

      onJobCreated({
        id: job.id,
        title: autoTitle,
        job_description: jobDescription,
        status: "processing",
        created_at: new Date().toISOString(),
        resume_count: filesToRank.length,
        jd_analysis_json: analysisData.jd_analysis,
        dynamic_weights_json: analysisData.dynamic_weights,
      });

      const resumeIds = await uploadFilesFromSnapshot(job.id, filesToRank);
      setRankingProgress(40);

      await rankAndPoll(job.id, resumeIds);

      setJobDescription("");
      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
      toast.success("Candidates ranked!");
    } catch (err: any) {
      handleRankingError(err);
    } finally {
      rankingFilesRef.current = new Set();
      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
      autoRankTriggered.current = false;
    }
  };

  const handleRankExisting = async () => {
    if (!user || !selectedJobId) return;
    const filesToRank = [...files];
    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
    setRanking(true); setRankingError(null);
    setRankingProgress(10); setScoredCount(0); setTotalToScore(filesToRank.length);

    try {
      if (!selectedJob?.jd_analysis_json) {
        await analyzeJd(selectedJobId);
        setRankingProgress(25);
      }

      const resumeIds = await uploadFilesFromSnapshot(selectedJobId, filesToRank);
      setRankingProgress(40);

      await rankAndPoll(selectedJobId, resumeIds);

      const { data: allResumes } = await supabase
        .from("resumes")
        .select("id, filename, file_path, candidate_name, created_at")
        .eq("job_id", selectedJobId)
        .order("created_at", { ascending: false });
      if (allResumes) setExistingResumes(allResumes);

      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
      toast.success("New resumes ranked!");
    } catch (err: any) {
      handleRankingError(err);
    } finally {
      rankingFilesRef.current = new Set();
      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
      autoRankTriggered.current = false;
    }
  };

  const uploadFilesFromSnapshot = async (jobId: string, filesToUpload: UploadedFile[]): Promise<string[]> => {
    if (!user) return [];
    const resumeIds: string[] = [];
    for (const { file, name } of filesToUpload) {
      const filePath = `${user.id}/${jobId}/${Date.now()}_${name}`;
      const { error: uploadError } = await supabase.storage.from("resumes").upload(filePath, file);
      if (uploadError) throw new Error(`Upload failed: ${uploadError.message}`);
      const { data: resume, error: resumeError } = await supabase
        .from("resumes")
        .insert({ job_id: jobId, filename: name, file_path: filePath })
        .select("id")
        .single();
      if (resumeError || !resume) throw new Error(resumeError?.message || "Failed to save resume");
      resumeIds.push(resume.id);
    }
    return resumeIds;
  };

  const rankAndPoll = async (jobId: string, resumeIds: string[]) => {
    const response = await fetch(
      `https://zkzontawprihrzpayeam.supabase.co/functions/v1/rank-resumes`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
        },
        body: JSON.stringify({ job_id: jobId, resume_ids: resumeIds }),
      }
    );

    if (!response.ok) {
      const errBody = await response.json().catch(() => ({}));
      const err: any = new Error(errBody.error || "Ranking failed");
      err.status = response.status;
      throw err;
    }
    setRankingProgress(60);

    for (let i = 0; i < 60; i++) {
      await new Promise((r) => setTimeout(r, 2000));
      const { data: resumeProgress } = await supabase.from("resumes").select("id, status").in("id", resumeIds);
      if (resumeProgress) {
        const done = resumeProgress.filter((r: any) => r.status === "done" || r.status === "failed").length;
        setScoredCount(done);
        const pct = resumeIds.length > 0 ? Math.round((done / resumeIds.length) * 35) : 0;
        setRankingProgress(Math.min(60 + pct, 95));
      }

      const { data: jobData } = await supabase.from("jobs").select("status").eq("id", jobId).single();
      if (jobData?.status === "completed") {
         const { data: allResumes } = await supabase.from("resumes").select("id, filename, file_path, candidate_name, parsed_json").eq("job_id", jobId);
         if (allResumes) {
           const allResumeIds = allResumes.map((r: any) => r.id);
            const { data: resultData } = await supabase
              .from("results")
              .select("id, resume_id, skill_score, experience_score, education_score, overall_score, missing_skills, red_flags, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
              .in("resume_id", allResumeIds);

            const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
            const merged: Result[] = (resultData ?? []).map((r: any) => {
              const resume = resumeMap.get(r.resume_id);
              const parsed = resume?.parsed_json as any;
              return {
                ...r,
                skill_score: r.skill_score ?? 0,
                experience_score: r.experience_score ?? 0,
                education_score: r.education_score ?? 0,
                overall_score: r.overall_score ?? 0,
                missing_skills: r.missing_skills ?? [],
                filename: resume?.filename ?? "Unknown",
                file_path: resume?.file_path ?? null,
                candidate_name: resume?.candidate_name ?? null,
                candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
                candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
                candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
              };
            });
          merged.sort((a, b) => b.overall_score - a.overall_score);
          setResults(merged);
        }
        setRankingProgress(100);
        await refreshProfile();
        setTimeout(() => { resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }, 200);
        return;
      }
      if (jobData?.status === "failed") throw new Error("Ranking failed on server");
    }
    throw new Error("Ranking timed out");
  };

  const handleRerank = async () => {
    if (!user || !selectedJobId || existingResumes.length === 0) return;
    setRanking(true); setRankingProgress(10);
    try {
      if (!selectedJob?.jd_analysis_json) {
        await analyzeJd(selectedJobId);
        setRankingProgress(20);
      }
      const resumeIds = existingResumes.map((r) => r.id);
      await supabase.from("results").delete().in("resume_id", resumeIds);
      for (const rid of resumeIds) {
        await supabase.from("resumes").update({ parsed_text: null, parsed_json: null } as any).eq("id", rid);
      }
      setResults([]); setRankingProgress(30);
      await supabase.from("jobs").update({ status: "processing" }).eq("id", selectedJobId);
      await rankAndPoll(selectedJobId, resumeIds);
      const { data: allResumes } = await supabase
        .from("resumes")
        .select("id, filename, file_path, candidate_name, created_at")
        .eq("job_id", selectedJobId)
        .order("created_at", { ascending: false });
      if (allResumes) setExistingResumes(allResumes);
      toast.success("All candidates re-ranked!");
    } catch (err: any) { toast.error(err.message || "Re-ranking failed."); }
    finally { setRanking(false); setRankingProgress(0); }
  };

  const downloadResume = async (filePath: string, filename: string) => {
    const { data, error } = await supabase.storage.from("resumes").download(filePath);
    if (error || !data) { toast.error("Download failed"); return; }
    const url = URL.createObjectURL(data);
    const a = document.createElement("a"); a.href = url; a.download = filename; a.click();
    URL.revokeObjectURL(url);
  };

  const deleteCount = deleteConfirm?.type === "bulk" ? selectedResumes.size : 1;

  const handleDismiss = (resumeId: string) => {
    setDismissedResumes((prev) => new Set(prev).add(resumeId));
    toast.success("Candidate dismissed");
  };

  const visibleResults = allResults.filter((r) => !dismissedResumes.has(r.resume_id));

  return (
    <div className="flex-1 overflow-auto">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Two-column: JD + Upload */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:items-stretch">
          {/* Job Description */}
          <Card className="flex flex-col">
            <CardHeader className="pb-3">
              <CardTitle className="text-lg">
                {isExistingJob ? "Job Description" : "Paste Job Description"}
              </CardTitle>
            </CardHeader>
            <CardContent className="flex-1 flex flex-col">
              {isExistingJob ? (
                <div className="bg-muted/50 rounded-md p-4 text-sm whitespace-pre-wrap flex-1 max-h-[300px] overflow-auto">
                  {selectedJob?.job_description}
                </div>
              ) : (
                <Textarea
                  placeholder="Paste the full job description here…"
                  value={jobDescription}
                  onFocus={() => { if (!isAuthenticated) { onAuthRequired(); } }}
                  onChange={(e) => { if (!isAuthenticated) { onAuthRequired(); return; } setJobDescription(e.target.value); }}
                  className="min-h-[200px] flex-1 resize-y"
                />
              )}
            </CardContent>
          </Card>

          {/* Upload Resumes */}
          <div className="space-y-4">
            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="text-lg">
                  {isExistingJob ? "Add More Resumes" : "Upload Resumes"}
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div
                  className={`border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-all duration-300 flex flex-col items-center justify-center ${
                    dragOver ? "border-primary bg-primary/5 scale-[1.01]" : "border-border hover:border-primary/50"
                  }`}
                  onDragOver={(e) => { e.preventDefault(); if (!isAuthenticated) return; setDragOver(true); }}
                  onDragLeave={() => setDragOver(false)}
                  onDrop={(e) => { if (!isAuthenticated) { e.preventDefault(); onAuthRequired(); return; } handleFileDrop(e); }}
                  onClick={() => { if (!isAuthenticated) { onAuthRequired(); return; } document.getElementById("file-input")?.click(); }}
                >
                  <Upload className="h-8 w-8 mx-auto mb-2 text-muted-foreground" />
                  <p className="text-sm text-muted-foreground">Drag & drop PDF/DOCX files, or click to browse</p>
                  <p className="text-xs text-muted-foreground mt-1">Max {maxResumes} files, {maxFileSizeMb}MB each</p>
                  <input id="file-input" type="file" className="hidden" multiple accept=".pdf,.docx" onChange={handleFileSelect} />
                </div>
                {files.length > 0 && (
                  <div className="space-y-2">
                    {files.map((f, i) => {
                      const isProcessing = rankingFilesRef.current.has(f.name) && ranking;
                      return (
                        <div key={i} className="flex items-center justify-between bg-secondary/50 rounded-md px-3 py-2 animate-fade-in">
                          <div className="flex items-center gap-2 text-sm">
                            {isProcessing ? <Loader2 className="h-4 w-4 text-primary animate-spin" /> : <FileText className="h-4 w-4 text-muted-foreground" />}
                            <span className={isProcessing ? "text-muted-foreground" : ""}>{f.name}</span>
                            {!isProcessing && ranking && <Badge variant="outline" className="text-xs">Queued</Badge>}
                          </div>
                          {!isProcessing && (
                            <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => removeFile(i)}>
                              <X className="h-3.5 w-3.5" />
                            </Button>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Per-Job Inbox Email */}
            {isExistingJob && (selectedJob as any)?.inbox_email && (
              <Card>
                <CardContent className="py-4 space-y-2">
                  <div className="flex items-center justify-between">
                    <div className="space-y-0.5">
                      <p className="text-sm font-medium">Job Inbox</p>
                      <p className="text-xs text-muted-foreground">Forward resumes for this specific job</p>
                    </div>
                    <Button variant="outline" size="sm" onClick={() => {
                      navigator.clipboard.writeText((selectedJob as any).inbox_email);
                      toast.success("Job inbox email copied!");
                    }} className="gap-1.5">
                      <Copy className="h-3.5 w-3.5" />
                      Copy
                    </Button>
                  </div>
                  <code className="block text-xs bg-muted/50 rounded px-2 py-1.5 font-mono truncate">
                    {(selectedJob as any).inbox_email}
                  </code>
                </CardContent>
              </Card>
            )}
            {/* Fallback User Inbox */}
            {user && profile?.inbox_email && !isExistingJob && (
              <Card>
                <CardContent className="py-4 flex items-center justify-between">
                  <div className="space-y-0.5">
                    <p className="text-sm font-medium">Resume Inbox</p>
                    <p className="text-xs text-muted-foreground">Forward resumes to auto-collect</p>
                  </div>
                  <Button variant="outline" size="sm" onClick={copyInboxEmail} className="gap-1.5">
                    <Copy className="h-3.5 w-3.5" />
                    Copy
                  </Button>
                </CardContent>
              </Card>
            )}
          </div>
        </div>

        {/* How It Works */}
        {!isExistingJob && allResults.length === 0 && (
          <div className="py-6">
            <h2 className="text-lg font-bold text-foreground text-center mb-6">How It Works</h2>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
              {[
                { icon: FileText, title: "Paste Job Description", desc: "AI extracts must-haves and weights automatically." },
                { icon: Upload, title: "Upload Resumes", desc: "Drag & drop PDF or DOCX files to get started." },
                { icon: CheckCircle2, title: "Get Ranked Results", desc: "Scored candidates with strengths and gaps." },
              ].map((item, i) => (
                <div key={i} className="text-center">
                  <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center mx-auto mb-3">
                    <item.icon className="h-5 w-5 text-primary" />
                  </div>
                  <h3 className="text-sm font-semibold text-foreground mb-1">{item.title}</h3>
                  <p className="text-xs text-muted-foreground leading-relaxed">{item.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Analyzing JD indicator */}
        {analyzingJd && (
          <div className="flex items-center gap-2 text-sm text-primary font-medium animate-fade-in">
            <Loader2 className="h-4 w-4 animate-spin" />
            Analyzing job description…
          </div>
        )}

        {/* Status & Progress */}
        <div className="space-y-3">
          {validationErrors.length > 0 && (
            <div className="text-sm text-destructive space-y-1">
              {validationErrors.map((err, i) => <p key={i}>• {err}</p>)}
            </div>
          )}
          {rankingError && (
            <div className={`rounded-lg border p-4 flex items-start gap-3 animate-fade-in ${
              rankingError.type === "credits" ? "border-destructive/40 bg-destructive/5" : "border-border bg-muted/50"
            }`}>
              <AlertTriangle className={`h-5 w-5 mt-0.5 shrink-0 ${rankingError.type === "credits" ? "text-destructive" : "text-muted-foreground"}`} />
              <div>
                <p className="text-sm font-medium">
                  {rankingError.type === "credits" ? "Not enough credits" : rankingError.type === "rate_limit" ? "Too many requests" : "Ranking failed"}
                </p>
                <p className="text-sm text-muted-foreground mt-0.5">{rankingError.message}</p>
              </div>
            </div>
          )}
          {ranking && (
            <div className="space-y-2 animate-fade-in">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-sm text-primary font-medium">
                  <Loader2 className="h-4 w-4 animate-spin" />
                  {rankingProgress < 25 ? "Analyzing job…" : rankingProgress < 40 ? "Uploading…" : rankingProgress < 60 ? "Parsing resumes…" : totalToScore > 0 ? `Scoring ${scoredCount}/${totalToScore}…` : "Scoring…"}
                </div>
              </div>
              <Progress value={rankingProgress} className="h-2" />
            </div>
          )}
        </div>

        {/* Score Summary Cards */}
        {visibleResults.length > 0 && <ScoreSummaryCards results={visibleResults} />}

        {/* Results Table */}
        {visibleResults.length > 0 && (
          <div ref={resultsRef}>
            <Card>
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between flex-wrap gap-2">
                  <CardTitle className="text-lg">
                    Results ({visibleResults.length})
                    {dismissedResumes.size > 0 && (
                      <Button variant="link" size="sm" className="ml-2 text-xs" onClick={() => setDismissedResumes(new Set())}>
                        Show {dismissedResumes.size} dismissed
                      </Button>
                    )}
                  </CardTitle>
                  <div className="flex items-center gap-2">
                    {selectedResumes.size > 0 && (
                      <>
                        <span className="text-sm text-muted-foreground">{selectedResumes.size} selected</span>
                        <Button variant="destructive" size="sm" className="gap-1.5" onClick={() => setDeleteConfirm({ type: "bulk" })}>
                          <Trash2 className="h-3.5 w-3.5" /> Delete
                        </Button>
                        <Button variant="ghost" size="sm" onClick={() => setSelectedResumes(new Set())}>Clear</Button>
                      </>
                    )}
                    {isExistingJob && existingResumes.length > 0 && (
                      <Button variant="outline" size="sm" className="gap-1.5" disabled={ranking} onClick={handleRerank}>
                        {ranking ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <RefreshCw className="h-3.5 w-3.5" />}
                        Re-rank
                      </Button>
                    )}
                  </div>
                </div>
              </CardHeader>
              <CardContent className="p-0">
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader className="sticky top-0 bg-card z-10">
                      <TableRow>
                        <TableHead className="w-10">
                          <Checkbox checked={visibleResults.length > 0 && selectedResumes.size === visibleResults.length} onCheckedChange={toggleSelectAll} />
                        </TableHead>
                        <TableHead className="w-14 text-center">#</TableHead>
                        <TableHead>Candidate</TableHead>
                        <TableHead className="w-32">Match</TableHead>
                        <TableHead className="w-20">Strength</TableHead>
                        <TableHead className="w-36"></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {visibleResults.map((r, index) => (
                        <CandidateRow
                          key={r.id}
                          result={r}
                          index={index}
                          isExpanded={expandedRows.has(r.id)}
                          isSelected={selectedResumes.has(r.resume_id)}
                          jobTitle={selectedJob?.title}
                          onToggleRow={toggleRow}
                          onToggleSelect={toggleSelectResume}
                          onDownload={downloadResume}
                          onDelete={(resumeId, filePath) => setDeleteConfirm({ type: "single", resumeId, filePath })}
                          onDismiss={handleDismiss}
                          formatCandidateName={formatCandidateName}
                        />
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </CardContent>
            </Card>
          </div>
        )}
      </div>

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteConfirm} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {deleteCount} resume{deleteCount > 1 ? "s" : ""}?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the resume{deleteCount > 1 ? "s" : ""} and any associated results.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteConfirm} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

export default JobDetailView;

import { useState, useCallback, useRef, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { usePlatformConfig } from "@/hooks/usePlatformConfig";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Progress } from "@/components/ui/progress";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle
} from "@/components/ui/alert-dialog";
import { toast } from "sonner";
import {
  Upload, Copy, Loader2, FileText,
  AlertTriangle, X, Trash2, RefreshCw, CheckCircle2
} from "lucide-react";
import ScoreSummaryCards from "@/components/ScoreSummaryCards";
import CandidateRow from "@/components/CandidateRow";
import type { PastJob, Result, ExistingResume } from "@/pages/Index";

interface JobDetailViewProps {
  selectedJobId: string | null;
  selectedJob: PastJob | null;
  results: Result[];
  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
  existingResumes: ExistingResume[];
  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
  onJobCreated: (job: PastJob) => void;
  onAuthRequired: () => void;
  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
  isAuthenticated?: boolean;
}

interface UploadedFile {
  file: File;
  name: string;
}

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const JobDetailView = ({
  selectedJobId,
  selectedJob,
  results,
  setResults,
  existingResumes,
  setExistingResumes,
  onJobCreated,
  onAuthRequired,
  onJobUpdated,
  isAuthenticated = true,
}: JobDetailViewProps) => {
  const { user, profile, refreshProfile } = useAuth();
  const { data: config } = usePlatformConfig();

  const [jobDescription, setJobDescription] = useState("");
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [ranking, setRanking] = useState(false);
  const [rankingProgress, setRankingProgress] = useState(0);
  const [scoredCount, setScoredCount] = useState(0);
  const [totalToScore, setTotalToScore] = useState(0);
  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
  const [dragOver, setDragOver] = useState(false);
  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [analyzingJd, setAnalyzingJd] = useState(false);
  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(new Set());

  const resultsRef = useRef<HTMLDivElement>(null);
  const rankingFilesRef = useRef<Set<string>>(new Set());
  const maxResumes = config?.max_resumes_per_job ?? 10;
  const maxFileSizeMb = config?.max_file_size_mb ?? 5;

  const isNewJobMode = selectedJobId === null;
  const isExistingJob = selectedJobId !== null && selectedJob !== null;

  const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const formatCandidateName = (filename: string) => {
    const name = filename.replace(/\.\w+$/, "");
    if (UUID_REGEX.test(name)) return `Candidate`;
    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
  };

  // Merge unranked resumes
  const resultResumeIds = new Set(results.map((r) => r.resume_id));
  const pendingResumes: Result[] = existingResumes
    .filter((r) => !resultResumeIds.has(r.id))
    .map((r) => ({
      id: `pending-${r.id}`,
      resume_id: r.id,
      skill_score: 0, experience_score: 0, education_score: 0, overall_score: 0,
      missing_skills: [], red_flags: {}, summary: null, interview_questions: null,
      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
      pending: true,
    }));
  const allResults = [...results, ...pendingResumes];

  // Selection helpers
  const toggleSelectResume = (resumeId: string) => {
    setSelectedResumes((prev) => {
      const next = new Set(prev);
      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
      return next;
    });
  };
  const toggleSelectAll = () => {
    if (selectedResumes.size === allResults.length) setSelectedResumes(new Set());
    else setSelectedResumes(new Set(allResults.map((r) => r.resume_id)));
  };

  // Delete logic
  const deleteResume = async (resumeId: string, filePath: string | null) => {
    if (filePath) await supabase.storage.from("resumes").remove([filePath]);
    await supabase.from("results").delete().eq("resume_id", resumeId);
    await supabase.from("resumes").delete().eq("id", resumeId);
    setResults((prev: Result[]) => prev.filter((r) => r.resume_id !== resumeId));
    setExistingResumes((prev: ExistingResume[]) => prev.filter((r) => r.id !== resumeId));
    setSelectedResumes((prev) => { const next = new Set(prev); next.delete(resumeId); return next; });
  };

  const handleDeleteConfirm = async () => {
    if (!deleteConfirm) return;
    setDeleting(true);
    try {
      if (deleteConfirm.type === "single" && deleteConfirm.resumeId) {
        await deleteResume(deleteConfirm.resumeId, deleteConfirm.filePath ?? null);
        toast.success("Resume deleted");
      } else if (deleteConfirm.type === "bulk") {
        const toDelete = allResults.filter((r) => selectedResumes.has(r.resume_id));
        for (const r of toDelete) await deleteResume(r.resume_id, r.file_path);
        toast.success(`${toDelete.length} resume(s) deleted`);
      }
    } catch { toast.error("Failed to delete"); }
    finally { setDeleting(false); setDeleteConfirm(null); }
  };

  // File handling
  const handleFileDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault(); setDragOver(false);
    const dropped = Array.from(e.dataTransfer.files).filter(
      (f) => f.type === "application/pdf" || f.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    );
    addFiles(dropped);
  }, [files, maxResumes, maxFileSizeMb]);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) addFiles(Array.from(e.target.files));
  };

  const addFiles = (newFiles: File[]) => {
    const currentCount = isExistingJob ? existingResumes.length + files.length : files.length;
    const valid = newFiles.filter((f) => {
      if (f.size > maxFileSizeMb * 1024 * 1024) { toast.error(`${f.name} exceeds ${maxFileSizeMb}MB limit`); return false; }
      return true;
    });
    const remaining = maxResumes - currentCount;
    if (valid.length > remaining) toast.error(`Max ${maxResumes} resumes per job`);
    const toAdd = valid.slice(0, Math.max(0, remaining)).map((f) => ({ file: f, name: f.name }));
    setFiles((prev) => [...prev, ...toAdd]);
  };

  const removeFile = (index: number) => setFiles((prev) => prev.filter((_, i) => i !== index));
  const toggleRow = (id: string) => {
    setExpandedRows((prev) => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  };

  const copyInboxEmail = () => {
    if (profile?.inbox_email) { navigator.clipboard.writeText(profile.inbox_email); toast.success("Inbox email copied!"); }
  };

  const validate = (): string[] => {
    const errors: string[] = [];
    if (isNewJobMode && !jobDescription.trim()) errors.push("Job description is required.");
    const filesToCheck = files.filter(f => !rankingFilesRef.current.has(f.name));
    if (filesToCheck.length === 0) errors.push("Upload at least one resume.");
    if (user && (profile?.credits ?? 0) < Math.min(filesToCheck.length, 20)) {
      errors.push(`Not enough credits. You need ${Math.min(filesToCheck.length, 20)} but have ${profile?.credits ?? 0}.`);
    }
    return errors;
  };

  // ── Analyze JD ──────────────────────────────────────────────
  const analyzeJd = async (jobId: string) => {
    setAnalyzingJd(true);
    try {
      const response = await fetch(
        `https://zkzontawprihrzpayeam.supabase.co/functions/v1/analyze-jd`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
          },
          body: JSON.stringify({ job_id: jobId }),
        }
      );
      if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.error || "JD analysis failed");
      }
      const data = await response.json();
      if (onJobUpdated) {
        onJobUpdated(jobId, {
          jd_analysis_json: data.jd_analysis,
          dynamic_weights_json: data.dynamic_weights,
        });
      }
      return data;
    } catch (err: any) {
      toast.error(err.message || "JD analysis failed");
      throw err;
    } finally {
      setAnalyzingJd(false);
    }
  };

  // ── Auto-rank ───────────────────────────────────────────────
  const autoRankTriggered = useRef(false);
  useEffect(() => {
    const unrankedFiles = files.filter(f => !rankingFilesRef.current.has(f.name));
    if (unrankedFiles.length > 0 && !ranking && !autoRankTriggered.current) {
      if (isNewJobMode && !jobDescription.trim()) return;
      autoRankTriggered.current = true;
      handleRankClick();
    }
    if (files.length === 0 && !ranking) autoRankTriggered.current = false;
  }, [files, ranking, isNewJobMode, jobDescription]);

  const handleRankingError = (err: any) => {
    const msg: string = err?.message || "Ranking failed.";
    if (msg.includes("Insufficient credits") || err?.status === 402) {
      setRankingError({ type: "credits", message: "You don't have enough credits to rank these resumes." });
    } else if (msg.includes("Rate limit") || err?.status === 429) {
      setRankingError({ type: "rate_limit", message: "Too many jobs in a short time. Please wait a minute and try again." });
    } else {
      setRankingError({ type: "generic", message: msg });
      toast.error(msg);
    }
  };

  const handleRankClick = () => {
    if (!user) { onAuthRequired(); return; }
    setRankingError(null);
    const errors = validate();
    setValidationErrors(errors);
    if (errors.length > 0) return;
    if (isExistingJob) handleRankExisting(); else handleRankNew();
  };

  const handleRankNew = async () => {
    if (!user) return;
    const filesToRank = [...files];
    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
    setRanking(true); setResults([]); setRankingError(null);
    setRankingProgress(5); setScoredCount(0); setTotalToScore(filesToRank.length);

    try {
      const autoTitle = (() => {
        const firstLine = jobDescription.trim().split("\n")[0].trim();
        return firstLine.slice(0, 50).trim() || `Job - ${new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`;
      })();

      const { data: job, error: jobError } = await supabase
        .from("jobs")
        .insert({ user_id: user.id, job_description: jobDescription, status: "pending", title: autoTitle } as any)
        .select("id")
        .single();
      if (jobError || !job) throw new Error(jobError?.message || "Failed to create job");
      setRankingProgress(10);

      const analysisData = await analyzeJd(job.id);
      setRankingProgress(25);

      onJobCreated({
        id: job.id,
        title: autoTitle,
        job_description: jobDescription,
        status: "processing",
        created_at: new Date().toISOString(),
        resume_count: filesToRank.length,
        jd_analysis_json: analysisData.jd_analysis,
        dynamic_weights_json: analysisData.dynamic_weights,
      });

      const resumeIds = await uploadFilesFromSnapshot(job.id, filesToRank);
      setRankingProgress(40);

      await rankAndPoll(job.id, resumeIds);

      setJobDescription("");
      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
      toast.success("Candidates ranked!");
    } catch (err: any) {
      handleRankingError(err);
    } finally {
      rankingFilesRef.current = new Set();
      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
      autoRankTriggered.current = false;
    }
  };

  const handleRankExisting = async () => {
    if (!user || !selectedJobId) return;
    const filesToRank = [...files];
    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
    setRanking(true); setRankingError(null);
    setRankingProgress(10); setScoredCount(0); setTotalToScore(filesToRank.length);

    try {
      if (!selectedJob?.jd_analysis_json) {
        await analyzeJd(selectedJobId);
        setRankingProgress(25);
      }

      const resumeIds = await uploadFilesFromSnapshot(selectedJobId, filesToRank);
      setRankingProgress(40);

      await rankAndPoll(selectedJobId, resumeIds);

      const { data: allResumes } = await supabase
        .from("resumes")
        .select("id, filename, file_path, candidate_name, created_at")
        .eq("job_id", selectedJobId)
        .order("created_at", { ascending: false });
      if (allResumes) setExistingResumes(allResumes);

      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
      toast.success("New resumes ranked!");
    } catch (err: any) {
      handleRankingError(err);
    } finally {
      rankingFilesRef.current = new Set();
      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
      autoRankTriggered.current = false;
    }
  };

  const uploadFilesFromSnapshot = async (jobId: string, filesToUpload: UploadedFile[]): Promise<string[]> => {
    if (!user) return [];
    const resumeIds: string[] = [];
    for (const { file, name } of filesToUpload) {
      const filePath = `${user.id}/${jobId}/${Date.now()}_${name}`;
      const { error: uploadError } = await supabase.storage.from("resumes").upload(filePath, file);
      if (uploadError) throw new Error(`Upload failed: ${uploadError.message}`);
      const { data: resume, error: resumeError } = await supabase
        .from("resumes")
        .insert({ job_id: jobId, filename: name, file_path: filePath })
        .select("id")
        .single();
      if (resumeError || !resume) throw new Error(resumeError?.message || "Failed to save resume");
      resumeIds.push(resume.id);
    }
    return resumeIds;
  };

  const rankAndPoll = async (jobId: string, resumeIds: string[]) => {
    const response = await fetch(
      `https://zkzontawprihrzpayeam.supabase.co/functions/v1/rank-resumes`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
        },
        body: JSON.stringify({ job_id: jobId, resume_ids: resumeIds }),
      }
    );

    if (!response.ok) {
      const errBody = await response.json().catch(() => ({}));
      const err: any = new Error(errBody.error || "Ranking failed");
      err.status = response.status;
      throw err;
    }
    setRankingProgress(60);

    for (let i = 0; i < 60; i++) {
      await new Promise((r) => setTimeout(r, 2000));
      const { data: resumeProgress } = await supabase.from("resumes").select("id, status").in("id", resumeIds);
      if (resumeProgress) {
        const done = resumeProgress.filter((r: any) => r.status === "done" || r.status === "failed").length;
        setScoredCount(done);
        const pct = resumeIds.length > 0 ? Math.round((done / resumeIds.length) * 35) : 0;
        setRankingProgress(Math.min(60 + pct, 95));
      }

      const { data: jobData } = await supabase.from("jobs").select("status").eq("id", jobId).single();
      if (jobData?.status === "completed") {
         const { data: allResumes } = await supabase.from("resumes").select("id, filename, file_path, candidate_name, parsed_json").eq("job_id", jobId);
         if (allResumes) {
           const allResumeIds = allResumes.map((r: any) => r.id);
            const { data: resultData } = await supabase
              .from("results")
              .select("id, resume_id, overall_score, missing_skills, red_flags, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
              .in("resume_id", allResumeIds);

            const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
            const merged: Result[] = (resultData ?? []).map((r: any) => {
              const resume = resumeMap.get(r.resume_id);
              const parsed = resume?.parsed_json as any;
              return {
                ...r,
                skill_score: r.skill_score ?? 0,
                experience_score: r.experience_score ?? 0,
                education_score: r.education_score ?? 0,
                overall_score: r.overall_score ?? 0,
                missing_skills: r.missing_skills ?? [],
                filename: resume?.filename ?? "Unknown",
                file_path: resume?.file_path ?? null,
                candidate_name: resume?.candidate_name ?? null,
                candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
                candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
                candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
              };
            });
          merged.sort((a, b) => b.overall_score - a.overall_score);
          setResults(merged);
        }
        setRankingProgress(100);
        await refreshProfile();
        setTimeout(() => { resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }, 200);
        return;
      }
      if (jobData?.status === "failed") throw new Error("Ranking failed on server");
    }
    throw new Error("Ranking timed out");
  };

  const handleRerank = async () => {
    if (!user || !selectedJobId || existingResumes.length === 0) return;
    setRanking(true); setRankingProgress(10);
    try {
      if (!selectedJob?.jd_analysis_json) {
        await analyzeJd(selectedJobId);
        setRankingProgress(20);
      }
      const resumeIds = existingResumes.map((r) => r.id);
      await supabase.from("results").delete().in("resume_id", resumeIds);
      for (const rid of resumeIds) {
        await supabase.from("resumes").update({ parsed_text: null, parsed_json: null } as any).eq("id", rid);
      }
      setResults([]); setRankingProgress(30);
      await supabase.from("jobs").update({ status: "processing" }).eq("id", selectedJobId);
      await rankAndPoll(selectedJobId, resumeIds);
      const { data: allResumes } = await supabase
        .from("resumes")
        .select("id, filename, file_path, candidate_name, created_at")
        .eq("job_id", selectedJobId)
        .order("created_at", { ascending: false });
      if (allResumes) setExistingResumes(allResumes);
      toast.success("All candidates re-ranked!");
    } catch (err: any) { toast.error(err.message || "Re-ranking failed."); }
    finally { setRanking(false); setRankingProgress(0); }
  };

  const downloadResume = async (filePath: string, filename: string) => {
    const { data, error } = await supabase.storage.from("resumes").download(filePath);
    if (error || !data) { toast.error("Download failed"); return; }
    const url = URL.createObjectURL(data);
    const a = document.createElement("a"); a.href = url; a.download = filename; a.click();
    URL.revokeObjectURL(url);
  };

  const deleteCount = deleteConfirm?.type === "bulk" ? selectedResumes.size : 1;

  const handleDismiss = (resumeId: string) => {
    setDismissedResumes((prev) => new Set(prev).add(resumeId));
    toast.success("Candidate dismissed");
  };

  const visibleResults = allResults.filter((r) => !dismissedResumes.has(r.resume_id));

  return (
    <div className="flex-1 overflow-auto">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Two-column: JD + Upload */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:items-stretch">
          {/* Job Description */}
          <Card className="flex flex-col">
            <CardHeader className="pb-3">
              <CardTitle className="text-lg">
                {isExistingJob ? "Job Description" : "Paste Job Description"}
              </CardTitle>
            </CardHeader>
            <CardContent className="flex-1 flex flex-col">
              {isExistingJob ? (
                <div className="bg-muted/50 rounded-md p-4 text-sm whitespace-pre-wrap flex-1 max-h-[300px] overflow-auto">
                  {selectedJob?.job_description}
                </div>
              ) : (
                <Textarea
                  placeholder="Paste the full job description here…"
                  value={jobDescription}
                  onFocus={() => { if (!isAuthenticated) { onAuthRequired(); } }}
                  onChange={(e) => { if (!isAuthenticated) { onAuthRequired(); return; } setJobDescription(e.target.value); }}
                  className="min-h-[200px] flex-1 resize-y"
                />
              )}
            </CardContent>
          </Card>

          {/* Upload Resumes */}
          <div className="space-y-4">
            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="text-lg">
                  {isExistingJob ? "Add More Resumes" : "Upload Resumes"}
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div
                  className={`border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-all duration-300 flex flex-col items-center justify-center ${
                    dragOver ? "border-primary bg-primary/5 scale-[1.01]" : "border-border hover:border-primary/50"
                  }`}
                  onDragOver={(e) => { e.preventDefault(); if (!isAuthenticated) return; setDragOver(true); }}
                  onDragLeave={() => setDragOver(false)}
                  onDrop={(e) => { if (!isAuthenticated) { e.preventDefault(); onAuthRequired(); return; } handleFileDrop(e); }}
                  onClick={() => { if (!isAuthenticated) { onAuthRequired(); return; } document.getElementById("file-input")?.click(); }}
                >
                  <Upload className="h-8 w-8 mx-auto mb-2 text-muted-foreground" />
                  <p className="text-sm text-muted-foreground">Drag & drop PDF/DOCX files, or click to browse</p>
                  <p className="text-xs text-muted-foreground mt-1">Max {maxResumes} files, {maxFileSizeMb}MB each</p>
                  <input id="file-input" type="file" className="hidden" multiple accept=".pdf,.docx" onChange={handleFileSelect} />
                </div>
                {files.length > 0 && (
                  <div className="space-y-2">
                    {files.map((f, i) => {
                      const isProcessing = rankingFilesRef.current.has(f.name) && ranking;
                      return (
                        <div key={i} className="flex items-center justify-between bg-secondary/50 rounded-md px-3 py-2 animate-fade-in">
                          <div className="flex items-center gap-2 text-sm">
                            {isProcessing ? <Loader2 className="h-4 w-4 text-primary animate-spin" /> : <FileText className="h-4 w-4 text-muted-foreground" />}
                            <span className={isProcessing ? "text-muted-foreground" : ""}>{f.name}</span>
                            {!isProcessing && ranking && <Badge variant="outline" className="text-xs">Queued</Badge>}
                          </div>
                          {!isProcessing && (
                            <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => removeFile(i)}>
                              <X className="h-3.5 w-3.5" />
                            </Button>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Per-Job Inbox Email */}
            {isExistingJob && (selectedJob as any)?.inbox_email && (
              <Card>
                <CardContent className="py-4 space-y-2">
                  <div className="flex items-center justify-between">
                    <div className="space-y-0.5">
                      <p className="text-sm font-medium">Job Inbox</p>
                      <p className="text-xs text-muted-foreground">Forward resumes for this specific job</p>
                    </div>
                    <Button variant="outline" size="sm" onClick={() => {
                      navigator.clipboard.writeText((selectedJob as any).inbox_email);
                      toast.success("Job inbox email copied!");
                    }} className="gap-1.5">
                      <Copy className="h-3.5 w-3.5" />
                      Copy
                    </Button>
                  </div>
                  <code className="block text-xs bg-muted/50 rounded px-2 py-1.5 font-mono truncate">
                    {(selectedJob as any).inbox_email}
                  </code>
                </CardContent>
              </Card>
            )}
            {/* Fallback User Inbox */}
            {user && profile?.inbox_email && !isExistingJob && (
              <Card>
                <CardContent className="py-4 flex items-center justify-between">
                  <div className="space-y-0.5">
                    <p className="text-sm font-medium">Resume Inbox</p>
                    <p className="text-xs text-muted-foreground">Forward resumes to auto-collect</p>
                  </div>
                  <Button variant="outline" size="sm" onClick={copyInboxEmail} className="gap-1.5">
                    <Copy className="h-3.5 w-3.5" />
                    Copy
                  </Button>
                </CardContent>
              </Card>
            )}
          </div>
        </div>

        {/* How It Works */}
        {!isExistingJob && allResults.length === 0 && (
          <div className="py-6">
            <h2 className="text-lg font-bold text-foreground text-center mb-6">How It Works</h2>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
              {[
                { icon: FileText, title: "Paste Job Description", desc: "AI extracts must-haves and weights automatically." },
                { icon: Upload, title: "Upload Resumes", desc: "Drag & drop PDF or DOCX files to get started." },
                { icon: CheckCircle2, title: "Get Ranked Results", desc: "Scored candidates with strengths and gaps." },
              ].map((item, i) => (
                <div key={i} className="text-center">
                  <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center mx-auto mb-3">
                    <item.icon className="h-5 w-5 text-primary" />
                  </div>
                  <h3 className="text-sm font-semibold text-foreground mb-1">{item.title}</h3>
                  <p className="text-xs text-muted-foreground leading-relaxed">{item.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Analyzing JD indicator */}
        {analyzingJd && (
          <div className="flex items-center gap-2 text-sm text-primary font-medium animate-fade-in">
            <Loader2 className="h-4 w-4 animate-spin" />
            Analyzing job description…
          </div>
        )}

        {/* Status & Progress */}
        <div className="space-y-3">
          {validationErrors.length > 0 && (
            <div className="text-sm text-destructive space-y-1">
              {validationErrors.map((err, i) => <p key={i}>• {err}</p>)}
            </div>
          )}
          {rankingError && (
            <div className={`rounded-lg border p-4 flex items-start gap-3 animate-fade-in ${
              rankingError.type === "credits" ? "border-destructive/40 bg-destructive/5" : "border-border bg-muted/50"
            }`}>
              <AlertTriangle className={`h-5 w-5 mt-0.5 shrink-0 ${rankingError.type === "credits" ? "text-destructive" : "text-muted-foreground"}`} />
              <div>
                <p className="text-sm font-medium">
                  {rankingError.type === "credits" ? "Not enough credits" : rankingError.type === "rate_limit" ? "Too many requests" : "Ranking failed"}
                </p>
                <p className="text-sm text-muted-foreground mt-0.5">{rankingError.message}</p>
              </div>
            </div>
          )}
          {ranking && (
            <div className="space-y-2 animate-fade-in">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-sm text-primary font-medium">
                  <Loader2 className="h-4 w-4 animate-spin" />
                  {rankingProgress < 25 ? "Analyzing job…" : rankingProgress < 40 ? "Uploading…" : rankingProgress < 60 ? "Parsing resumes…" : totalToScore > 0 ? `Scoring ${scoredCount}/${totalToScore}…` : "Scoring…"}
                </div>
              </div>
              <Progress value={rankingProgress} className="h-2" />
            </div>
          )}
        </div>

        {/* Score Summary Cards */}
        {visibleResults.length > 0 && <ScoreSummaryCards results={visibleResults} />}

        {/* Results Table */}
        {visibleResults.length > 0 && (
          <div ref={resultsRef}>
            <Card>
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between flex-wrap gap-2">
                  <CardTitle className="text-lg">
                    Results ({visibleResults.length})
                    {dismissedResumes.size > 0 && (
                      <Button variant="link" size="sm" className="ml-2 text-xs" onClick={() => setDismissedResumes(new Set())}>
                        Show {dismissedResumes.size} dismissed
                      </Button>
                    )}
                  </CardTitle>
                  <div className="flex items-center gap-2">
                    {selectedResumes.size > 0 && (
                      <>
                        <span className="text-sm text-muted-foreground">{selectedResumes.size} selected</span>
                        <Button variant="destructive" size="sm" className="gap-1.5" onClick={() => setDeleteConfirm({ type: "bulk" })}>
                          <Trash2 className="h-3.5 w-3.5" /> Delete
                        </Button>
                        <Button variant="ghost" size="sm" onClick={() => setSelectedResumes(new Set())}>Clear</Button>
                      </>
                    )}
                    {isExistingJob && existingResumes.length > 0 && (
                      <Button variant="outline" size="sm" className="gap-1.5" disabled={ranking} onClick={handleRerank}>
                        {ranking ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <RefreshCw className="h-3.5 w-3.5" />}
                        Re-rank
                      </Button>
                    )}
                  </div>
                </div>
              </CardHeader>
              <CardContent className="p-0">
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader className="sticky top-0 bg-card z-10">
                      <TableRow>
                        <TableHead className="w-10">
                          <Checkbox checked={visibleResults.length > 0 && selectedResumes.size === visibleResults.length} onCheckedChange={toggleSelectAll} />
                        </TableHead>
                        <TableHead className="w-14 text-center">#</TableHead>
                        <TableHead>Candidate</TableHead>
                        <TableHead className="w-32">Match</TableHead>
                        <TableHead className="w-20">Strength</TableHead>
                        <TableHead className="w-36"></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {visibleResults.map((r, index) => (
                        <CandidateRow
                          key={r.id}
                          result={r}
                          index={index}
                          isExpanded={expandedRows.has(r.id)}
                          isSelected={selectedResumes.has(r.resume_id)}
                          jobTitle={selectedJob?.title}
                          onToggleRow={toggleRow}
                          onToggleSelect={toggleSelectResume}
                          onDownload={downloadResume}
                          onDelete={(resumeId, filePath) => setDeleteConfirm({ type: "single", resumeId, filePath })}
                          onDismiss={handleDismiss}
                          formatCandidateName={formatCandidateName}
                        />
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </CardContent>
            </Card>
          </div>
        )}
      </div>

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteConfirm} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {deleteCount} resume{deleteCount > 1 ? "s" : ""}?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the resume{deleteCount > 1 ? "s" : ""} and any associated results.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteConfirm} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

export default JobDetailView;

