   441→      const resumeIds = existingResumes.map((r) => r.id);
   442→      await supabase.from("results").delete().in("resume_id", resumeIds);
   443→      for (const rid of resumeIds) {
   444→        await supabase.from("resumes").update({ parsed_text: null, parsed_json: null } as any).eq("id", rid);
   445→      }
   446→      setResults([]); setRankingProgress(30);
   447→      await supabase.from("jobs").update({ status: "processing" }).eq("id", selectedJobId);
   448→      await rankAndPoll(selectedJobId, resumeIds);
   449→      const { data: allResumes } = await supabase
   450→        .from("resumes")
   451→        .select("id, filename, file_path, candidate_name, created_at")
   452→        .eq("job_id", selectedJobId)
   453→        .order("created_at", { ascending: false });
   454→      if (allResumes) setExistingResumes(allResumes);
