   162→      weights[firstKey] = Math.round((weights[firstKey] + (1.0 - finalTotal)) * 1000) / 1000;
   163→    }
   164→
   165→    // Generate JD embedding
   166→    const embeddingResponse = await fetch("https://api.openai.com/v1/embeddings", {
   167→      method: "POST",
   168→      headers: {
   169→        Authorization: `Bearer ${OPENAI_API_KEY}`,
   170→        "Content-Type": "application/json",
   171→      },
   172→      body: JSON.stringify({
   173→        model: "text-embedding-3-small",
   174→        input: jdText.slice(0, 8000),
   175→      }),
   176→    });
   177→
   178→    if (!embeddingResponse.ok) {
   179→      throw new Error(`Embedding API error: ${embeddingResponse.status}`);
   180→    }
   181→
   182→    const embeddingData = await embeddingResponse.json();
   183→    const jdEmbedding = embeddingData.data?.[0]?.embedding;
   184→
   185→    // Store everything
   186→    const { error: updateError } = await supabase
   187→      .from("jobs")
   188→      .update({
   189→        jd_analysis_json: jdAnalysis,
   190→        dynamic_weights_json: weights,
   191→        jd_embedding: JSON.stringify(jdEmbedding),
   192→      } as any)
   193→      .eq("id", job_id);
   194→
   195→    if (updateError) throw new Error(`Failed to save JD analysis: ${updateError.message}`);
   196→
   197→    console.log(`JD analysis complete for job ${job_id}: ${dimensions.length} dimensions, ${Object.keys(weights).length} weights`);
   198→
   199→    return new Response(
   200→      JSON.stringify({
   201→        success: true,
   202→        jd_analysis: jdAnalysis,
   203→        dynamic_weights: weights,
   204→      }),
   205→      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
   206→    );
   207→  } catch (err) {
   208→    console.error("analyze-jd error:", err);
   209→    return new Response(
   210→      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
   211→      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
   212→    );
   213→  }
   214→});
