   240→    } else if (msg.includes("Rate limit") || err?.status === 429) {
   241→      setRankingError({ type: "rate_limit", message: "Too many jobs in a short time. Please wait a minute and try again." });
   242→    } else {
   243→      setRankingError({ type: "generic", message: msg });
