   263→
   264→    try {
   265→      const autoTitle = (() => {
   266→        const firstLine = jobDescription.trim().split("\n")[0].trim();
   267→        return firstLine.slice(0, 50).trim() || `Job - ${new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`;
   268→      })();
   269→
   270→      const { data: job, error: jobError } = await supabase
   271→        .from("jobs")
   272→        .insert({ user_id: user.id, job_description: jobDescription, status: "pending", title: autoTitle } as any)
   273→        .select("id")
