   291→
   292→      const resumeIds = await uploadFilesFromSnapshot(job.id, filesToRank);
   293→      setRankingProgress(40);
   294→
   295→      await rankAndPoll(job.id, resumeIds);
   296→
   297→      setJobDescription("");
   298→      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
   299→      toast.success("Candidates ranked!");
   300→    } catch (err: any) {
   301→      handleRankingError(err);
   302→    } finally {
   303→      rankingFilesRef.current = new Set();
   304→      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
   305→      autoRankTriggered.current = false;
   306→    }
   307→  };
