   345→  const uploadFilesFromSnapshot = async (jobId: string, filesToUpload: UploadedFile[]): Promise<string[]> => {
   346→    if (!user) return [];
   347→    const resumeIds: string[] = [];
   348→    for (const { file, name } of filesToUpload) {
   349→      const filePath = `${user.id}/${jobId}/${Date.now()}_${name}`;
   350→      const { error: uploadError } = await supabase.storage.from("resumes").upload(filePath, file);
   351→      if (uploadError) throw new Error(`Upload failed: ${uploadError.message}`);
   352→      const { data: resume, error: resumeError } = await supabase
   353→        .from("resumes")
   354→        .insert({ job_id: jobId, filename: name, file_path: filePath })
   355→        .select("id")
   356→        .single();
   357→      if (resumeError || !resume) throw new Error(resumeError?.message || "Failed to save resume");
   358→      resumeIds.push(resume.id);
   359→    }
   360→    return resumeIds;
