   363→  const rankAndPoll = async (jobId: string, resumeIds: string[]) => {
   364→    const response = await fetch(
   365→      `https://zkzontawprihrzpayeam.supabase.co/functions/v1/rank-resumes`,
   366→      {
   367→        method: "POST",
   368→        headers: {
   369→          "Content-Type": "application/json",
   370→          Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
   371→        },
   372→        body: JSON.stringify({ job_id: jobId, resume_ids: resumeIds }),
   373→      }
   374→    );
   375→
   376→    if (!response.ok) {
   377→      const errBody = await response.json().catch(() => ({}));
   378→      const err: any = new Error(errBody.error || "Ranking failed");
   379→      err.status = response.status;
   380→      throw err;
   381→    }
   382→    setRankingProgress(60);
   383→
   384→    for (let i = 0; i < 60; i++) {
   385→      await new Promise((r) => setTimeout(r, 2000));
   386→      const { data: resumeProgress } = await supabase.from("resumes").select("id, status").in("id", resumeIds);
   387→      if (resumeProgress) {
   388→        const done = resumeProgress.filter((r: any) => r.status === "done" || r.status === "failed").length;
   389→        setScoredCount(done);
   390→        const pct = resumeIds.length > 0 ? Math.round((done / resumeIds.length) * 35) : 0;
   391→        setRankingProgress(Math.min(60 + pct, 95));
   392→      }
   393→
   394→      const { data: jobData } = await supabase.from("jobs").select("status").eq("id", jobId).single();
   395→      if (jobData?.status === "completed") {
   396→         const { data: allResumes } = await supabase.from("resumes").select("id, filename, file_path, candidate_name, parsed_json").eq("job_id", jobId);
   397→         if (allResumes) {
   398→           const allResumeIds = allResumes.map((r: any) => r.id);
   399→            const { data: resultData } = await supabase
   400→              .from("results")
   401→              .select("id, resume_id, overall_score, missing_skills, red_flags, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
   402→              .in("resume_id", allResumeIds);
   403→
   404→            const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
   405→            const merged: Result[] = (resultData ?? []).map((r: any) => {
   406→              const resume = resumeMap.get(r.resume_id);
   407→              const parsed = resume?.parsed_json as any;
   408→              return {
   409→                ...r,
   410→                overall_score: r.overall_score ?? 0,
   411→                missing_skills: r.missing_skills ?? [],
   412→                filename: resume?.filename ?? "Unknown",
   413→                file_path: resume?.file_path ?? null,
   414→                candidate_name: resume?.candidate_name ?? null,
   415→                candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
   416→                candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
   417→                candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
   418→              };
   419→            });
   420→          merged.sort((a, b) => b.overall_score - a.overall_score);
   421→          setResults(merged);
   422→        }
   423→        setRankingProgress(100);
   424→        await refreshProfile();
   425→        setTimeout(() => { resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }, 200);
   426→        return;
   427→      }
   428→      if (jobData?.status === "failed") throw new Error("Ranking failed on server");
   429→    }
   430→    throw new Error("Ranking timed out");
   431→  };
