import CandidateRow from "@/components/CandidateRow";
import type { PastJob, Result, ExistingResume } from "@/pages/Index";

interface JobDetailViewProps {
  selectedJobId: string | null;
  selectedJob: PastJob | null;
  results: Result[];
  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
  existingResumes: ExistingResume[];
  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
  onJobCreated: (job: PastJob) => void;
  onAuthRequired: () => void;
  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
  isAuthenticated?: boolean;
}

interface UploadedFile {
  file: File;
  name: string;
}

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const JobDetailView = ({
  selectedJobId,
  selectedJob,
  results,
  setResults,
  existingResumes,
  setExistingResumes,
  onJobCreated,
  onAuthRequired,
  onJobUpdated,
  isAuthenticated = true,
}: JobDetailViewProps) => {
  const { user, profile, refreshProfile } = useAuth();
  const { data: config } = usePlatformConfig();

  const [jobDescription, setJobDescription] = useState("");
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [ranking, setRanking] = useState(false);
  const [rankingProgress, setRankingProgress] = useState(0);
  const [scoredCount, setScoredCount] = useState(0);
  const [totalToScore, setTotalToScore] = useState(0);
  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
  const [dragOver, setDragOver] = useState(false);
  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [analyzingJd, setAnalyzingJd] = useState(false);
  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());

  const resultsRef = useRef<HTMLDivElement>(null);
  const rankingFilesRef = useRef<Set<string>>(new Set());
  const maxResumes = config?.max_resumes_per_job ?? 10;
  const maxFileSizeMb = config?.max_file_size_mb ?? 5;

import { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger } from
"@/components/ui/dropdown-menu";
import { Zap, LogOut, Settings, Coins, User, ShieldCheck, AlertTriangle } from "lucide-react";
import { Link } from "react-router-dom";
import AuthDialog from "@/components/AuthDialog";

const AppHeader = () => {
  const { user, profile, isAdmin, signOut } = useAuth();
  const [authOpen, setAuthOpen] = useState(false);
  const [authTab, setAuthTab] = useState<"signin" | "signup">("signin");
  const navigate = useNavigate();

  const openAuth = (tab: "signin" | "signup") => {
    setAuthTab(tab);
    setAuthOpen(true);
  };

  return (
    <>
      <header className="border-b border-border bg-card">
        <div className="mx-auto max-w-[1200px] px-4 sm:px-6 flex items-center justify-between h-14">
          <Link to="/" className="flex items-center gap-2">
            <Zap className="h-5 w-5 text-primary" />
            <span className="font-semibold text-foreground tracking-tight">​Rankora    







    </span>
          </Link>
          <div className="flex items-center gap-3">
            {user ? <>
                {(profile?.credits ?? 0) < 3 ? <Badge variant="destructive" className="gap-1.5 py-1 px-3 animate-pulse cursor-pointer" onClick={() => navigate("/settings")}>

                    <AlertTriangle className="h-3.5 w-3.5" />
                    {profile?.credits ?? 0} credits left
                  </Badge> : <Badge variant="secondary"
              className="gap-1.5 py-1 px-3 cursor-pointer"
              onClick={() => navigate("/settings")}>

                    <Coins className="h-3.5 w-3.5" />
                    {profile?.credits ?? 0} credits
                  </Badge>
              }
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button variant="ghost" size="icon" className="rounded-full">
                      <User className="h-4 w-4" />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-48">
                    <DropdownMenuItem onClick={() => navigate("/settings")}>
                      <Settings className="h-4 w-4 mr-2" />
                      Settings
                    </DropdownMenuItem>
                    {isAdmin &&
                  <DropdownMenuItem onClick={() => navigate("/admin")}>
                        <ShieldCheck className="h-4 w-4 mr-2" />
                        Admin
                      </DropdownMenuItem>
                  }
                    <DropdownMenuSeparator />
                    <DropdownMenuItem onClick={signOut}>
                      <LogOut className="h-4 w-4 mr-2" />
                      Sign out
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </> :

            <>
                <Button variant="ghost" size="sm" onClick={() => openAuth("signin")}>
                  Sign in
                </Button>
                <Button size="sm" onClick={() => openAuth("signup")}>
                  Sign up free
                </Button>
              </>
            }
          </div>
        </div>
      </header>
      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab={authTab} />
    </>);

};

export default AppHeader;

