import { useState, useMemo, useRef, useEffect } from "react";
import { cn } from "@/lib/utils";
import { Plus, Clock, Loader2, Briefcase, Search, MoreHorizontal, Pencil, Trash2, FileText } from "lucide-react";
import { format } from "date-fns";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { SidebarInput } from "@/components/ui/sidebar";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
} from "@/components/ui/sidebar";

interface PastJob {
  id: string;
  title: string | null;
  job_description: string;
  status: string;
  created_at: string;
  resume_count: number;
}

interface JobSidebarProps {
  pastJobs: PastJob[];
  selectedJobId: string | null;
  loadingPastJobs: boolean;
  onSelectJob: (jobId: string) => void;
  onNewJob: () => void;
  onRenameJob: (jobId: string, newTitle: string) => void;
  onDeleteJob: (jobId: string) => void;
  onAuthRequired?: () => void;
  isAuthenticated?: boolean;
}

function getDisplayTitle(job: PastJob): string {
  if (job.title) return job.title;
  const firstLine = job.job_description.trim().split("\n")[0].trim();
  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
}

const JobSidebar = ({ pastJobs, selectedJobId, loadingPastJobs, onSelectJob, onNewJob, onRenameJob, onDeleteJob, onAuthRequired, isAuthenticated = true }: JobSidebarProps) => {
  const [search, setSearch] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState("");
  const [deleteJobId, setDeleteJobId] = useState<string | null>(null);
  const editInputRef = useRef<HTMLInputElement>(null);

  const filteredJobs = useMemo(() => {
    if (!search.trim()) return pastJobs;
    const q = search.toLowerCase();
    return pastJobs.filter(
      (job) =>
        getDisplayTitle(job).toLowerCase().includes(q) ||
        job.job_description.toLowerCase().includes(q)
    );
  }, [pastJobs, search]);

  useEffect(() => {
    if (editingId && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingId]);

  const startEditing = (job: PastJob) => {
    setEditingId(job.id);
    setEditValue(getDisplayTitle(job));
  };

  const saveRename = async () => {
    if (!editingId || !editValue.trim()) {
      setEditingId(null);
      return;
    }
    try {
      const { error } = await supabase
        .from("jobs")
        .update({ title: editValue.trim() } as any)
        .eq("id", editingId);
      if (error) throw error;
      onRenameJob(editingId, editValue.trim());
      toast.success("Job renamed");
    } catch {
      toast.error("Failed to rename job");
    }
    setEditingId(null);
  };

  const cancelEditing = () => setEditingId(null);

  const confirmDelete = () => {
    if (deleteJobId) {
      onDeleteJob(deleteJobId);
      setDeleteJobId(null);
    }
  };

  return (
    <>
      <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
        <SidebarHeader className="p-4 space-y-3">
          <Button onClick={() => { if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; } onNewJob(); }} className="w-full gap-2" size="sm">
            <Plus className="h-4 w-4" />
            New Job
          </Button>
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
            <SidebarInput
              placeholder="Search jobs…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-8"
            />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup>
            <SidebarGroupLabel className="px-4 flex items-center gap-2">
              <Briefcase className="h-4 w-4" />
              <span>Job History</span>
              {search && <span className="ml-auto text-[10px]">({filteredJobs.length})</span>}
            </SidebarGroupLabel>
            <SidebarGroupContent>
              {!isAuthenticated ? (
                <p className="text-sm text-muted-foreground px-4 py-6 text-center">
                  Sign in to see your jobs
                </p>
              ) : loadingPastJobs ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
                </div>
              ) : filteredJobs.length === 0 ? (
                <p className="text-sm text-muted-foreground px-4 py-6 text-center">
                  {search ? "No matching jobs found." : "No jobs yet. Create your first one!"}
                </p>
              ) : (
                <SidebarMenu className="space-y-1.5 px-2">
                  {filteredJobs.map((job) => (
                    <SidebarMenuItem key={job.id}>
                      {editingId === job.id ? (
                        <div className="mx-0 rounded-lg border border-primary/50 bg-card shadow-sm px-3 py-2">
                          <Input
                            ref={editInputRef}
                            value={editValue}
                            onChange={(e) => setEditValue(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === "Enter") saveRename();
                              if (e.key === "Escape") cancelEditing();
                            }}
                            onBlur={saveRename}
                            className="h-7 text-sm"
                          />
                        </div>
                      ) : (
                        <SidebarMenuButton
                          isActive={selectedJobId === job.id}
                          onClick={() => onSelectJob(job.id)}
                          className={cn(
                            "flex flex-col items-start gap-1 h-auto py-2.5 px-3 group/item",
                            "rounded-lg border bg-card shadow-sm",
                            "hover:shadow-md hover:border-border transition-all",
                            selectedJobId === job.id
                              ? "border-l-2 border-l-primary bg-sidebar-accent shadow-md"
                              : "border-border/60"
                          )}
                        >
                          <div className="flex items-center gap-1 w-full">
                            <span className="text-sm leading-snug line-clamp-2 flex-1">
                              {getDisplayTitle(job)}
                            </span>
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
                                <button className="opacity-0 group-hover/item:opacity-100 transition-opacity p-0.5 rounded hover:bg-accent shrink-0">
                                  <MoreHorizontal className="h-3.5 w-3.5 text-muted-foreground" />
                                </button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end" className="w-36">
                                <DropdownMenuItem onClick={(e) => { e.stopPropagation(); startEditing(job); }}>
                                  <Pencil className="h-3.5 w-3.5 mr-2" />
                                  Rename
                                </DropdownMenuItem>
                                <DropdownMenuItem
                                  onClick={(e) => { e.stopPropagation(); setDeleteJobId(job.id); }}
                                  className="text-destructive focus:text-destructive"
                                >
                                  <Trash2 className="h-3.5 w-3.5 mr-2" />
                                  Delete
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </div>
                          <div className="flex items-center gap-2 w-full">
                            <span className="text-[10px] text-muted-foreground flex items-center gap-0.5">
                              <FileText className="h-2.5 w-2.5" />
                              {job.resume_count} {job.resume_count === 1 ? "resume" : "resumes"}
                            </span>
                            <span className="text-[10px] text-muted-foreground flex items-center gap-0.5 ml-auto">
                              <Clock className="h-2.5 w-2.5" />
                              {format(new Date(job.created_at), "MMM d, yyyy")}
                            </span>
                          </div>
                        </SidebarMenuButton>
                      )}
                    </SidebarMenuItem>
                  ))}
                </SidebarMenu>
              )}
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
      </Sidebar>

      <AlertDialog open={!!deleteJobId} onOpenChange={(open) => !open && setDeleteJobId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this job?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete this job and all its resumes. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

export default JobSidebar;

